<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppShell from '@/components/shell/AppShell.vue'
import SubmitOverview from '@/components/common/SubmitOverview.vue'
import SessionAnswerCard from '@/components/common/SessionAnswerCard.vue'
import { Grid2X2 } from 'lucide-vue-next'
import { questionTypeLabel } from '@/utils/questionTypes'
import '@/styles/exam-workspace.css'
import { renderMarkdown } from '@/utils/markdown'
import { useExamStore } from '@/stores/examStore'
const route=useRoute(),router=useRouter(),store=useExamStore(),remaining=ref(0),overviewOpen=ref(false),cardOpen=ref(false);let clock,snapshotClock,serverRemainingMs=0,monotonicStart=0;const timers=new Map()
const q=computed(()=>store.currentQuestion),timeText=computed(()=>`${String(Math.floor(remaining.value/60)).padStart(2,'0')}:${String(remaining.value%60).padStart(2,'0')}`)
const answeredCount=computed(()=>Object.values(store.answers).filter(value=>Array.isArray(value)?value.length>0:value!==null&&value!=='').length)
function anchorClock(){serverRemainingMs=Math.max(0,new Date(store.session.deadline_at).getTime()-new Date(store.session.server_time).getTime());monotonicStart=performance.now()}
function syncClock(){remaining.value=Math.max(0,Math.ceil((serverRemainingMs-(performance.now()-monotonicStart))/1000))}
onMounted(async()=>{try{await store.load(route.params.sessionId);if(store.session.status==='completed'){router.replace(`/apply/exam/sessions/${route.params.sessionId}/report`);return}if(store.session.status==='created')await store.start();anchorClock();syncClock();clock=setInterval(async()=>{syncClock();if(!remaining.value){clearInterval(clock);await finish(true)}},1000);snapshotClock=setInterval(()=>store.saveRecoverySnapshot().catch(()=>{}),30000)}catch{/* store.error is rendered below */}})
onBeforeUnmount(()=>{clearInterval(clock);clearInterval(snapshotClock);store.saveRecoverySnapshot().catch(()=>{});for(const timer of timers.values())clearTimeout(timer)})
function scheduleSave(id, immediate=false){store.markDirty(id);if(timers.has(id))clearTimeout(timers.get(id));timers.set(id,setTimeout(()=>store.save(id).catch(()=>{}),immediate?0:600))}
function toggleMulti(questionId, optionId){
  const current=Array.isArray(store.answers[questionId])?store.answers[questionId]:[]
  const next=current.includes(optionId)?current.filter((id)=>id!==optionId):[...current,optionId]
  store.answers[questionId]=next
  scheduleSave(questionId,true)
}
async function move(index){if(q.value)await store.save(q.value.question_id).catch(()=>{});store.currentIndex=index;cardOpen.value=false;store.saveRecoverySnapshot().catch(()=>{})}
async function finish(timeout=false){for(const timer of timers.values())clearTimeout(timer);if(!timeout&&!overviewOpen.value){overviewOpen.value=true;return}overviewOpen.value=false;await store.submit();router.replace(`/apply/exam/sessions/${route.params.sessionId}/report`)}
function jumpTo(index){overviewOpen.value=false;store.currentIndex=index}
</script>
<template><AppShell><template #topbar-title>自主考试 · <span class="timer">{{timeText}}</span></template><main v-if="q" class="exam-runner"><header><span>已作答 {{answeredCount}} / {{store.session.questions.length}}</span><div class="exam-tools"><span :class="store.saveState" role="status">{{store.saveState==='saving'?'保存中…':store.saveState==='error'?'保存失败':store.saveState==='unsaved'?'等待保存':'已保存'}}</span><button type="button" class="card-trigger" :aria-expanded="cardOpen" @click="cardOpen=!cardOpen"><Grid2X2 :size="17" />答题卡</button></div></header><div class="progress-track" role="progressbar" aria-label="已作答题数" :aria-valuenow="answeredCount" :aria-valuemax="store.session.questions.length" aria-valuemin="0"><span :style="{width: `${answeredCount/store.session.questions.length*100}%`}" /></div><p v-if="store.error" class="error" role="alert">{{store.error}}</p><div class="exam-workspace"><div class="exam-main"><section class="question"><div class="meta">第 {{q.position}} / {{store.session.questions.length}} 题 · {{questionTypeLabel(q.question_type)}}</div><div class="math" v-html="renderMarkdown(q.content)"/><div v-if="q.question_type==='choice'" class="options"><label v-for="o in q.options||[]" :key="o.id"><input v-model="store.answers[q.question_id]" type="radio" :value="o.id" @change="scheduleSave(q.question_id,true)"><span class="option-key">{{o.id}}</span><span v-html="renderMarkdown(o.text)"/></label></div><div v-else-if="q.question_type==='multi_choice'" class="options"><span class="multi-hint">多选题：勾选所有正确选项</span><label v-for="o in q.options||[]" :key="o.id"><input :checked="(store.answers[q.question_id]||[]).includes(o.id)" type="checkbox" :value="o.id" @change="toggleMulti(q.question_id,o.id)"><span class="option-key">{{o.id}}</span><span v-html="renderMarkdown(o.text)"/></label></div><div v-else-if="q.question_type==='judge'" class="options"><label><input v-model="store.answers[q.question_id]" type="radio" value="true" @change="scheduleSave(q.question_id,true)">对</label><label><input v-model="store.answers[q.question_id]" type="radio" value="false" @change="scheduleSave(q.question_id,true)">错</label></div><input v-else v-model="store.answers[q.question_id]" class="answer" placeholder="输入答案" @input="scheduleSave(q.question_id)" @blur="scheduleSave(q.question_id,true)"></section><nav><button :disabled="store.currentIndex===0" @click="move(store.currentIndex-1)">上一题</button><button class="primary" v-if="store.currentIndex<store.session.questions.length-1" @click="move(store.currentIndex+1)">下一题</button><button v-else class="primary" :disabled="store.loading" @click="finish(false)">交卷</button></nav></div><SessionAnswerCard :questions="store.session.questions" :answers="store.answers" :current-index="store.currentIndex" :open="cardOpen" :busy="store.loading" @close="cardOpen=false" @jump="move" @finish="finish(false)" /></div><SubmitOverview :visible="overviewOpen" :questions="store.session?.questions||[]" :answers="store.answers" :current-index="store.currentIndex" :submitting="store.loading" title="交卷前总览 · 自主考试" @confirm="finish(false)" @cancel="overviewOpen=false" @jump="jumpTo"/></main><p v-else-if="store.error" class="loading" role="alert">{{store.error}}</p><p v-else class="loading" role="status">正在恢复考试…</p></AppShell></template>
